<?php
 namespace QQWorld\Customer\Test\TestCase; use QQWorld\Mtf\TestCase\Injectable; use QQWorld\Cms\Test\Page\CmsIndex; use QQWorld\Customer\Test\Fixture\Customer; use QQWorld\Customer\Test\Page\CustomerAccountEdit; use QQWorld\Customer\Test\Page\CustomerAccountIndex; use QQWorld\Customer\Test\Page\CustomerAccountLogin; class ChangeCustomerPasswordTest extends Injectable { const MVP = 'yes'; protected $cmsIndex; protected $customerAccountLogin; protected $customerAccountIndex; protected $customerAccountEdit; public function __inject( CmsIndex $cmsIndex, CustomerAccountLogin $customerAccountLogin, CustomerAccountIndex $customerAccountIndex, CustomerAccountEdit $customerAccountEdit ) { $this->cmsIndex = $cmsIndex; $this->customerAccountLogin = $customerAccountLogin; $this->customerAccountIndex = $customerAccountIndex; $this->customerAccountEdit = $customerAccountEdit; } public function test(Customer $initialCustomer, Customer $customer) { $initialCustomer->persist(); $this->objectManager->create( \QQWorld\Customer\Test\TestStep\LoginCustomerOnFrontendStep::class, ['customer' => $initialCustomer] )->run(); $this->cmsIndex->getLinksBlock()->openLink('My Account'); $this->customerAccountIndex->getInfoBlock()->openChangePassword(); $this->customerAccountEdit->getAccountInfoForm()->fill($customer); $this->customerAccountEdit->getAccountInfoForm()->submit(); } } 